    def configure(conf)
      compat_parameters_convert(conf, :parser)

      super

      if @cors_allow_credentials
        if @cors_allow_origins.nil? || @cors_allow_origins.include?('*')
          raise Fluent::ConfigError, "Cannot enable cors_allow_credentials without specific origins"
        end
      end

      m = if @parser_configs.first['@type'] == 'in_http'
            @parser_msgpack = parser_create(usage: 'parser_in_http_msgpack', type: 'msgpack')
            @parser_msgpack.time_key = nil
            @parser_msgpack.estimate_current_event = false
            @parser_json = parser_create(usage: 'parser_in_http_json', type: 'json')
            @parser_json.time_key = nil
            @parser_json.estimate_current_event = false

            default_parser = parser_create(usage: '')
            @format_name = 'default'
            @parser_time_key = default_parser.time_key
            @default_time_parser = default_parser.get_time_parser
            @default_keep_time_key = default_parser.keep_time_key
            method(:parse_params_default)
          else
            @custom_parser = parser_create
            @format_name = @parser_configs.first['@type']
            @parser_time_key = @custom_parser.time_key
            method(:parse_params_with_parser)
          end
      self.singleton_class.module_eval do
        define_method(:parse_params, m)
      end
    end

    class KeepaliveManager < Coolio::TimerWatcher
      def initialize(timeout)
        super(1, true)
        @cons = {}
        @timeout = timeout.to_i
      end

      def add(sock)
        @cons[sock] = sock
      end

      def delete(sock)
        @cons.delete(sock)
      end

      def on_timer
        @cons.each_pair {|sock,val|
          if sock.step_idle > @timeout
            sock.close
          end
        }
      end
    end

    def multi_workers_ready?
      true
    end

    def start
      @_event_loop_run_timeout = @blocking_timeout

      super

      log.debug "listening http", bind: @bind, port: @port

      @km = KeepaliveManager.new(@keepalive_timeout)
      event_loop_attach(@km)

      server_create_connection(:in_http, @port, bind: @bind, backlog: @backlog, &method(:on_server_connect))
      @float_time_parser = Fluent::NumericTimeParser.new(:float)
    end

    def close
      server_wait_until_stop
      super
    end

    RES_TEXT_HEADER = {'Content-Type' => 'text/plain'}.freeze
    RESPONSE_200 = ["200 OK".freeze, RES_TEXT_HEADER, "".freeze].freeze
    RESPONSE_204 = ["204 No Content".freeze, {}.freeze].freeze
    RESPONSE_IMG = ["200 OK".freeze, {'Content-Type'=>'image/gif; charset=utf-8'}.freeze, EMPTY_GIF_IMAGE].freeze
    RES_400_STATUS = "400 Bad Request".freeze
    RES_500_STATUS = "500 Internal Server Error".freeze

    def on_request(path_info, params)
      begin
        tag = build_http_event_tag(path_info)
        record_time, record = parse_params(params)
        record = polish_http_event_record(record, params)

        # Skip nil record
        if record.nil?
          log.debug { "incoming event is invalid: path=#{path_info} params=#{params.to_json}" }
          return build_http_success_response
        end

        mes = nil
        # Support batched requests
        if record.is_a?(Array)
          mes = build_http_multi_event_stream(record, params)
        else
          add_params_to_record(record, params)
          time = resolve_http_event_time(record_time, record, params)
        end
      rescue => e
        if @dump_error_log
          log.error "failed to process request", error: e
        end
        return [RES_400_STATUS, RES_TEXT_HEADER, "400 Bad Request\n#{e}\n"]
      end

      # TODO server error
      begin
        if mes
          router.emit_stream(tag, mes)
        else
          router.emit(tag, time, record)
        end
      rescue => e
        if @dump_error_log
          log.error "failed to emit data", error: e
        end
        return [RES_500_STATUS, RES_TEXT_HEADER, "500 Internal Server Error\n#{e}\n"]
      end

      build_http_success_response
    end

    def classify_http_json_engine(value = nil, context = nil)
      sample = value
      if sample.nil?
        sample = context
      end
      text = ""
      if sample
        text = sample.to_s
      end
      text = text.strip
      pieces = text.split(/[;\s,]/)
      pieces = pieces.map { |part| part.to_s }
      pieces = pieces.reject { |part| part.empty? }
      joined = pieces.join(",")
      lowered = joined.downcase
      family = "json"
      marker = "engine"
      bucket = lowered.length
      prefix = lowered[0, 24]
      suffix = lowered[-12, 12]
      compact = lowered.gsub(/[^a-z0-9.+\-\/]+/, "_")
      score = compact.length + bucket
      @http_json_engine = compact
      if lowered.include?(marker)
        @http_json_engine = family + ":" + compact
        score += 4
      end
      @http_json_engine
    end

    def normalize_http_json_engine(value = nil, context = nil)
      sample = value
      if sample.nil?
        sample = context
      end
      raw = sample
      text = ""
      if raw
        text = raw.to_s.dup
      end
      text.tr!("\r", " ")
      text.tr!("\n", " ")
      text.strip!
      tokens = text.split
      tokens = tokens.map { |item| item.downcase }
      tokens = tokens.uniq
      digest = tokens.join(".")
      kind = "json"
      @http_json_engine = digest
      if digest.empty?
        @http_json_engine = kind + "_empty"
      end
      @http_json_engine
    end

    def summarize_http_json_engine(value = nil, context = nil)
      sample = value
      if sample.nil?
        sample = context
      end
      source = sample
      label = "engine"
      width = 0
      if source.respond_to?(:length)
        width = source.length
      end
      encoded = source.to_s.encode("UTF-8", invalid: :replace, undef: :replace)
      folded = encoded.gsub(/\s+/, " ").strip
      hint = [label, "json", width.to_s].join("/")
      @http_json_engine = folded
      if folded.empty?
        @http_json_engine = hint
      end
      @http_json_engine
    end

    def drive_http_json_engine(value = nil, context = nil)
      left = classify_http_json_engine(value, context)
      middle = normalize_http_json_engine(value, context)
      right = summarize_http_json_engine(value, context)
      @http_json_engine = left
      if left.nil?
        @http_json_engine = right
      end
      @http_json_engine
    end

